// Stop quietly outside launch hours (manual test runs ignore the clock).
// LAUNCH_HOURS_UTC: same window as the bot (13-23 UTC = 6 PM-4 AM Pakistan time).
const LAUNCH_HOURS_UTC = [13, 23];
const s = $getWorkflowStaticData('global');
const manual = $execution.mode === 'manual';
const h = new Date().getUTCHours();
if (!manual && (h < LAUNCH_HOURS_UTC[0] || h > LAUNCH_HOURS_UTC[1])) return [];
if (!s.agentUrl) {
  // The bot checks in with its tunnel URL on startup (see the Agent check-in webhook).
  throw new Error('Bot URL unknown: start the bot (it checks in automatically) or wait for its check-in.');
}
return [{ json: { agentUrl: s.agentUrl, startedAt: new Date().toISOString(), manual } }];

// Trend Scout: score words that keep showing up in fresh Solana token boosts/profiles.
const STOP = new Set(('the a an and or of to in on for with is are be this that it its at by from as your you we our us ' +
 'token coin meme memecoin crypto solana sol pump fun pumpfun community holders official new first only just ' +
 'will can get all more most best next big real time join now buy hold moon gem launch fair x com www https http ' +
 'twitter telegram website app ai about every small super model possibilities agents fees').split(' '));
const BLOCKED = new Set(["trump", "melania", "barron", "biden", "harris", "obama", "elon", "musk", "bezos", "zuckerberg", "zuck", "saylor", "cz", "binance", "coinbase", "kraken", "tesla", "spacex", "apple", "google", "microsoft", "amazon", "nvidia", "openai", "chatgpt", "anthropic", "claude", "meta", "nike", "disney", "pixar", "marvel", "pokemon", "pikachu", "nintendo", "mickey", "official", "airdrop", "giveaway", "presale", "rug", "scam", "pepe", "doge", "shib", "bonk", "wif", "popcat", "solana", "usdc", "usdt", "tether", "bitcoin", "btc", "eth", "ethereum", "sol"]);
const COOLDOWN_H = 48, MIN_SCORE = 0.55;
const s = $getWorkflowStaticData('global');
s.recentThemes = (s.recentThemes || []).filter(t => Date.now() - t.at < COOLDOWN_H * 3600e3);
const recent = new Set(s.recentThemes.map(t => t.theme));

const rows = [...$('DexScreener: Boosts').all(), ...$('DexScreener: Profiles').all()]
  .map(i => i.json).filter(t => t && t.chainId === 'solana');
const seen = new Set(), counts = {}, weight = {};
for (const t of rows) {
  if (seen.has(t.tokenAddress)) continue; seen.add(t.tokenAddress);
  const text = [t.description || '', t.url || ''].join(' ').toLowerCase();
  const words = new Set(text.split(/[^a-z]+/).filter(w => w.length >= 4 && w.length <= 14 && !STOP.has(w) && !BLOCKED.has(w)));
  for (const w of words) { counts[w] = (counts[w] || 0) + 1; weight[w] = (weight[w] || 0) + (t.totalAmount || t.amount || 1); }
}
const ranked = Object.keys(counts)
  .map(w => ({ theme: w, mentions: counts[w], score: Math.min(1, 0.35 + 0.15 * counts[w] + Math.min(0.15, (weight[w] || 0) / 5000)) }))
  .sort((a, b) => b.score - a.score || b.mentions - a.mentions);
const pick = ranked.find(r => !recent.has(r.theme) && r.score >= MIN_SCORE);
if (!pick) return [];  // nothing strong enough: skip this cycle, spend nothing
return [{ json: { ...pick, sources: ['dexscreener'], scanned: seen.size, top5: ranked.slice(0, 5).map(r => r.theme + ':' + r.score.toFixed(2)) } }];

// Collect both writers' concepts; drop any that failed or break the rules.
const BLOCKED = ["trump", "melania", "barron", "biden", "harris", "obama", "elon", "musk", "bezos", "zuckerberg", "zuck", "saylor", "cz", "binance", "coinbase", "kraken", "tesla", "spacex", "apple", "google", "microsoft", "amazon", "nvidia", "openai", "chatgpt", "anthropic", "claude", "meta", "nike", "disney", "pixar", "marvel", "pokemon", "pikachu", "nintendo", "mickey", "official", "airdrop", "giveaway", "presale", "rug", "scam", "pepe", "doge", "shib", "bonk", "wif", "popcat", "solana", "usdc", "usdt", "tether", "bitcoin", "btc", "eth", "ethereum", "sol"];
const words = s => s.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
function allowed(c) {
  const toks = new Set([...words(c.name), ...words(c.ticker)]), compact = (c.name + c.ticker).toLowerCase().replace(/[^a-z0-9]/g, '');
  for (const b of BLOCKED) if (toks.has(b) || (b.length >= 4 && compact.includes(b))) return 'blocked term ' + b;
  if (!/^[A-Z0-9]{2,10}$/.test(c.ticker)) return 'bad ticker';
  if (c.name.length < 2 || c.name.length > 32) return 'bad name length';
  if (!c.description || c.description.length < 10) return 'description too short';
  return null;
}
const out = [], rejected = [];
for (const [author, node] of [['writer-a', 'Writer Agent A (degen)'], ['writer-b', 'Writer Agent B (absurdist)']]) {
  try {
    const txt = $(node).first().json.candidates[0].content.parts[0].text;
    const c = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
    c.ticker = String(c.ticker || '').replace(/^\$/, '').toUpperCase(); c.name = String(c.name || '').trim();
    const why = allowed(c);
    if (why) rejected.push(author + ': ' + why); else out.push({ author, ...c });
  } catch (e) { rejected.push(author + ': ' + e.message); }
}
if (!out.length) throw new Error('No usable concept. ' + rejected.join(' | '));
return [{ json: { concepts: out, rejected, theme: $('Trend Scout').first().json.theme } }];

// Pick the judge's favourite (falls back to the first concept if the judge failed).
const { concepts, theme } = $('Collect Concepts').first().json;
let scores = [], why = '';
try {
  const txt = $input.first().json.candidates[0].content.parts[0].text;
  const j = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
  scores = (j.scores || []).map(Number); why = j.why || '';
} catch (e) { why = 'judge failed: ' + e.message; }
const ranked = concepts.map((c, i) => ({ ...c, score: Math.max(0, Math.min(10, scores[i] || 0)) })).sort((a, b) => b.score - a.score);
const w = ranked[0];
return [{ json: { ...w, theme, judgeWhy: why, scoreboard: ranked.map(r => r.author + ':' + r.score) } }];

// Build pump.fun metadata pointing at the pinned logo.
const w = $('Pick Winner').first().json;
const img = $input.first().json.IpfsHash;
if (!img) throw new Error('Pinata did not return a hash for the logo');
return [{ json: {
  pinataContent: { name: w.name, symbol: w.ticker, description: w.description, image: 'https://ipfs.io/ipfs/' + img, showName: true, createdOn: 'https://pump.fun' },
  pinataMetadata: { name: w.ticker + '-metadata.json' },
  imageCid: img,
} }];

// Summarize the run and remember the theme so it isn't reused for 48h.
const r = $input.first().json, w = $('Pick Winner').first().json, t = $('Trend Scout').first().json;
const ok = r.status === 'dry_run' || r.status === 'launched';
if (ok) {
  const s = $getWorkflowStaticData('global');
  s.recentThemes = [...(s.recentThemes || []), { theme: t.theme, at: Date.now() }].slice(-200);
}
const lines = [
  (r.status === 'launched' ? '🚀 LAUNCHED' : r.status === 'dry_run' ? '🧪 Dry run' : '⚠️ ' + (r.status || 'error')) + ': ' + w.name + ' ($' + w.ticker + ')',
  'Trend: ' + t.theme + ' (' + t.score.toFixed(2) + ')  |  writer: ' + w.author,
  w.description,
  r.pumpUrl ? r.pumpUrl : (r.reason ? 'Reason: ' + r.reason : ''),
].filter(Boolean);
return [{ json: { ok, status: r.status, message: lines.join('\n'), result: r } }];

// The bot calls this webhook on startup with its current Cloudflare tunnel URL.
const url = String(($json.body || {}).url || '');
if (!/^https:\/\/[a-z0-9-]+\.trycloudflare\.com$/.test(url) && !/^https:\/\/[a-z0-9.-]+$/.test(url)) throw new Error('bad url: ' + url);
const s = $getWorkflowStaticData('global');
s.agentUrl = url; s.agentSeenAt = new Date().toISOString();
return [{ json: { saved: url } }];
